/* eslint-disable */
/*! Uwebly Style Companion v3.0.1 | (c) 2026 Bmdu Studio | https://style.uwebly.com */
(function (global) {
  'use strict';

  var Uwebly = {
    version: '3.0.1',

    // Theme Management
    initTheme: function () {
      var savedTheme = null;
      try {
        savedTheme = localStorage.getItem('uwebly-theme');
      } catch (e) {
        void e;
      }

      if (savedTheme) {
        document.documentElement.setAttribute('data-theme', savedTheme);
      }

      document.addEventListener('click', function (e) {
        var toggle = e.target.closest('[data-uwebly-theme="toggle"]');
        if (toggle) {
          e.preventDefault();
          var current = document.documentElement.getAttribute('data-theme') === 'dark' ? 'dark' : 'light';
          var next = current === 'dark' ? 'light' : 'dark';
          document.documentElement.setAttribute('data-theme', next);
          try {
            localStorage.setItem('uwebly-theme', next);
          } catch (err) {
            void err;
          }
          var event = new CustomEvent('uwebly:theme-change', { detail: { theme: next } });
          window.dispatchEvent(event);
        }
      });
    },

    setTheme: function (theme) {
      if (theme === 'light' || theme === 'dark') {
        document.documentElement.setAttribute('data-theme', theme);
        try {
          localStorage.setItem('uwebly-theme', theme);
        } catch (err) {
          void err;
        }
      }
    },

    getTheme: function () {
      return document.documentElement.getAttribute('data-theme') || 'light';
    },

    // Modal Management
    showModal: function (target) {
      var el = typeof target === 'string' ? document.querySelector(target) : target;
      if (!el) return;
      el.classList.remove('closing');
      el.classList.add('active');
      document.body.style.overflow = 'hidden';
      el.dispatchEvent(new CustomEvent('uwebly:modal-shown', { detail: { modal: el } }));
    },

    hideModal: function (target) {
      var el = typeof target === 'string' ? document.querySelector(target) : target;
      if (!el) return;
      el.classList.add('closing');
      setTimeout(function () {
        el.classList.remove('active', 'closing');
        document.body.style.overflow = '';
        el.dispatchEvent(new CustomEvent('uwebly:modal-hidden', { detail: { modal: el } }));
      }, 180);
    },

    // BottomSheet Management
    showBottomSheet: function (target) {
      var el = typeof target === 'string' ? document.querySelector(target) : target;
      if (!el) return;
      el.classList.remove('closing');
      el.classList.add('active');
      document.body.style.overflow = 'hidden';
      el.dispatchEvent(new CustomEvent('uwebly:bottomsheet-shown', { detail: { bottomsheet: el } }));
    },

    hideBottomSheet: function (target) {
      var el = typeof target === 'string' ? document.querySelector(target) : target;
      if (!el) return;
      el.classList.add('closing');
      setTimeout(function () {
        el.classList.remove('active', 'closing');
        document.body.style.overflow = '';
        el.dispatchEvent(new CustomEvent('uwebly:bottomsheet-hidden', { detail: { bottomsheet: el } }));
      }, 220);
    },

    // Drawer / Offcanvas Management
    showDrawer: function (target) {
      var el = typeof target === 'string' ? document.querySelector(target) : target;
      if (!el) return;
      el.classList.add('active');
      document.body.style.overflow = 'hidden';
      el.dispatchEvent(new CustomEvent('uwebly:drawer-shown', { detail: { drawer: el } }));
    },

    hideDrawer: function (target) {
      var el = typeof target === 'string' ? document.querySelector(target) : target;
      if (!el) return;
      el.classList.remove('active');
      document.body.style.overflow = '';
      el.dispatchEvent(new CustomEvent('uwebly:drawer-hidden', { detail: { drawer: el } }));
    },

    // Accordion / Collapse Management
    toggleAccordion: function (itemEl) {
      if (!itemEl) return;
      var isOpen = itemEl.classList.contains('open') || itemEl.classList.contains('active');
      if (isOpen) {
        itemEl.classList.remove('open', 'active');
      } else {
        itemEl.classList.add('open', 'active');
      }
    },

    // Dropdown Management
    toggleDropdown: function (dropdownEl) {
      if (!dropdownEl) return;
      var menu = dropdownEl.querySelector('.uwebly-dropdown-menu');
      if (!menu) return;
      var isOpen = menu.classList.contains('show') || dropdownEl.classList.contains('open');
      this.closeAllDropdowns();
      if (!isOpen) {
        dropdownEl.classList.add('open');
        menu.classList.add('show');
      }
    },

    closeAllDropdowns: function () {
      var openMenus = document.querySelectorAll('.uwebly-dropdown-menu.show');
      openMenus.forEach(function (m) {
        m.classList.remove('show');
      });
      var openContainers = document.querySelectorAll('.uwebly-dropdown.open');
      openContainers.forEach(function (c) {
        c.classList.remove('open');
      });
    },

    // Toast Notification Banner
    toast: function (message, duration) {
      duration = duration || 3000;
      var toast = document.createElement('div');
      toast.className = 'uwebly-toast';
      toast.style.cssText =
        'position:fixed;bottom:24px;right:24px;z-index:9999;background:var(--card-bg,#fff);color:var(--text-color,#111);border:1px solid var(--border,#e0e0e0);border-radius:12px;padding:12px 18px;font-size:13px;font-weight:600;box-shadow:none;display:flex;align-items:center;gap:8px;';
      toast.textContent = message;
      document.body.appendChild(toast);
      setTimeout(function () {
        toast.style.transition = 'opacity .2s ease, transform .2s ease';
        toast.style.opacity = '0';
        toast.style.transform = 'translateY(8px)';
        setTimeout(function () {
          if (toast.parentNode) toast.parentNode.removeChild(toast);
        }, 200);
      }, duration);
    },

    // Global Event Delegate
    init: function () {
      this.initTheme();

      document.addEventListener('click', function (e) {
        // Modal Open
        var modalOpenBtn = e.target.closest('[data-uwebly-toggle="modal"]');
        if (modalOpenBtn) {
          e.preventDefault();
          var targetId = modalOpenBtn.getAttribute('data-uwebly-target');
          if (targetId) Uwebly.showModal(targetId);
        }

        // Modal Dismiss
        var modalCloseBtn = e.target.closest('[data-uwebly-dismiss="modal"]');
        if (modalCloseBtn) {
          e.preventDefault();
          var modalContainer = modalCloseBtn.closest('.uwebly-modal-overlay, .report-modal-overlay, [data-uwebly-modal]');
          if (modalContainer) Uwebly.hideModal(modalContainer);
        }

        // Overlay Backdrop Click (Dismiss Modal)
        if (e.target.matches('.uwebly-modal-overlay, .report-modal-overlay, [data-uwebly-modal-overlay]')) {
          if (e.target.getAttribute('data-uwebly-backdrop') !== 'static') {
            Uwebly.hideModal(e.target);
          }
        }

        // BottomSheet Open
        var bottomsheetOpenBtn = e.target.closest('[data-uwebly-toggle="bottomsheet"]');
        if (bottomsheetOpenBtn) {
          e.preventDefault();
          var bsTarget = bottomsheetOpenBtn.getAttribute('data-uwebly-target');
          if (bsTarget) Uwebly.showBottomSheet(bsTarget);
        }

        // BottomSheet Dismiss
        var bottomsheetCloseBtn = e.target.closest('[data-uwebly-dismiss="bottomsheet"]');
        if (bottomsheetCloseBtn) {
          e.preventDefault();
          var bsContainer = bottomsheetCloseBtn.closest('.uwebly-bottomsheet-overlay, [data-uwebly-bottomsheet]');
          if (bsContainer) Uwebly.hideBottomSheet(bsContainer);
        }

        // BottomSheet Overlay Backdrop Click
        if (e.target.matches('.uwebly-bottomsheet-overlay, [data-uwebly-bottomsheet-overlay]')) {
          if (e.target.getAttribute('data-uwebly-backdrop') !== 'static') {
            Uwebly.hideBottomSheet(e.target);
          }
        }

        // Drawer Open
        var drawerOpenBtn = e.target.closest('[data-uwebly-toggle="drawer"]');
        if (drawerOpenBtn) {
          e.preventDefault();
          var drawerTarget = drawerOpenBtn.getAttribute('data-uwebly-target');
          if (drawerTarget) Uwebly.showDrawer(drawerTarget);
        }

        // Drawer Dismiss
        var drawerCloseBtn = e.target.closest('[data-uwebly-dismiss="drawer"]');
        if (drawerCloseBtn) {
          e.preventDefault();
          var drawerContainer = drawerCloseBtn.closest('.message-drawer-overlay, [data-uwebly-drawer]');
          if (drawerContainer) Uwebly.hideDrawer(drawerContainer);
        }

        // Accordion Toggle
        var accordionHeader = e.target.closest('.uwebly-accordion-header, [data-uwebly-toggle="accordion"], [data-uwebly-toggle="collapse"]');
        if (accordionHeader) {
          e.preventDefault();
          var item = accordionHeader.closest('.uwebly-accordion-item');
          if (item) {
            Uwebly.toggleAccordion(item);
          }
        }

        // Dropdown Toggle
        var dropdownToggle = e.target.closest('[data-uwebly-toggle="dropdown"]');
        if (dropdownToggle) {
          e.preventDefault();
          e.stopPropagation();
          var dropdownContainer = dropdownToggle.closest('.uwebly-dropdown');
          if (dropdownContainer) {
            Uwebly.toggleDropdown(dropdownContainer);
          }
        } else {
          // Click outside closes dropdowns
          if (!e.target.closest('.uwebly-dropdown-menu')) {
            Uwebly.closeAllDropdowns();
          }
        }
      });

      // ESC key closes modals/bottomsheets/drawers/dropdowns
      document.addEventListener('keydown', function (e) {
        if (e.key === 'Escape') {
          var activeModal = document.querySelector('.uwebly-modal-overlay.active, .report-modal-overlay.active');
          if (activeModal) Uwebly.hideModal(activeModal);
          var activeBs = document.querySelector('.uwebly-bottomsheet-overlay.active');
          if (activeBs) Uwebly.hideBottomSheet(activeBs);
          var activeDrawer = document.querySelector('.message-drawer-overlay.active');
          if (activeDrawer) Uwebly.hideDrawer(activeDrawer);
          Uwebly.closeAllDropdowns();
        }
      });
    }
  };

  // Auto initialize when DOM is ready
  if (typeof document !== 'undefined') {
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', function () {
        Uwebly.init();
      });
    } else {
      Uwebly.init();
    }
  }

  global.Uwebly = Uwebly;
})(typeof window !== 'undefined' ? window : this);
